package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.ListMemberLoansUseCase.MemberLoanPage;

import java.util.List;

public record MemberLoansResponse(List<MemberLoanResponse> items, int page, int size, long totalCount) {

    static MemberLoansResponse from(MemberLoanPage loanPage) {
