    void lists_only_unreturned_loans_with_paging_and_total_count() throws Exception {
        String memberId = registerMember("강하윤");
        String firstLoanId = loanBook(registerBook("Clean Code"), memberId, LocalDate.of(2026, 2, 2));
        String returnedLoanId = loanBook(registerBook("Refactoring"), memberId, LocalDate.of(2026, 2, 3));
        String thirdLoanId = loanBook(registerBook("Effective Java"), memberId, LocalDate.of(2026, 2, 4));

        mockMvc.perform(post("/loans/{loanId}/return", returnedLoanId))
                .andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "0").param("size", "1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].loanId").value(firstLoanId))
                .andExpect(jsonPath("$.items[0].title").value("Clean Code"))
                .andExpect(jsonPath("$.items[0].loanedAt").value("2026-02-02"))
                .andExpect(jsonPath("$.items[0].dueAt").value("2026-02-16"))
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(1))
                .andExpect(jsonPath("$.totalCount").value(2));

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "1").param("size", "1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].loanId").value(thirdLoanId))
                .andExpect(jsonPath("$.totalCount").value(2));

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "2").param("size", "1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(0))
                .andExpect(jsonPath("$.totalCount").value(2));
    }

    @Test
    void member_without_loans_gets_an_empty_page() throws Exception {
        String memberId = registerMember("오지후");

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(0))
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(20))
                .andExpect(jsonPath("$.totalCount").value(0));
    }

    @Test
    void unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void negative_page_or_out_of_range_size_returns_400() throws Exception {
        String memberId = registerMember("윤서연");

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "-1"))
                .andExpect(status().isBadRequest());

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("size", "0"))
                .andExpect(status().isBadRequest());

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("size", "101"))
                .andExpect(status().isBadRequest());
    }

    private String loanBook(String bookId, String memberId, LocalDate loanedAt) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBody(bookId, memberId, loanedAt))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String registerMember(String name) throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    record LoanBody(String bookId, String memberId, LocalDate loanedAt) {
    }
}
