package com.example.lending.application.service;

import com.example.lending.application.port.in.ListMemberLoanHistoryUseCase;
import com.example.lending.application.port.out.LoadLoanHistoryPort;
import com.example.lending.application.port.out.LoadLoanHistoryPort.LoanHistory;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.domain.Loan;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.UUID;

@Service
@Transactional(readOnly = true)
public class ListMemberLoanHistoryService implements ListMemberLoanHistoryUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadLoanHistoryPort loadLoanHistoryPort;

    public ListMemberLoanHistoryService(LoadMemberPort loadMemberPort, LoadLoanHistoryPort loadLoanHistoryPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadLoanHistoryPort = loadLoanHistoryPort;
    }

    @Override
    public List<LoanHistoryEntry> listLoanHistory(UUID memberId) {
        loadMemberPort.loadMember(memberId)
                .orElseThrow(() -> new MemberNotFoundException(memberId));
        return loadLoanHistoryPort.loadLoanHistory(memberId).stream()
                .map(history -> toEntry(history))
                .toList();
    }

    private LoanHistoryEntry toEntry(LoanHistory history) {
        Loan loan = history.loan();
        Long lateFee = loan.isReturned() ? loan.getLateFee() : null;
        return new LoanHistoryEntry(loan.getId(), history.title(), loan.getLoanedAt(), loan.getReturnedAt(), lateFee);
    }
}

