package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.time.LocalDate;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberLoanHistoryIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void history_includes_returned_loans_newest_loan_first_with_late_fee() throws Exception {
        String memberId = registerMember("강하윤");
        String lateLoanId = loanBook(registerBook("History Late Book"), memberId, LocalDate.of(2026, 1, 1));
        String onTimeLoanId = loanBook(registerBook("History On Time Book"), memberId, LocalDate.of(2026, 1, 10));
        String activeLoanId = loanBook(registerBook("History Active Book"), memberId, LocalDate.of(2026, 2, 2));

        // 기한 2026-01-15 를 5일 넘겨 반납: 500원
        returnBook(lateLoanId, "2026-01-20");
        // 기한 2026-01-24 이전에 반납: 연체 없음
        returnBook(onTimeLoanId, "2026-01-12");

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(3))
                .andExpect(jsonPath("$[0].loanId").value(activeLoanId))
                .andExpect(jsonPath("$[0].title").value("History Active Book"))
                .andExpect(jsonPath("$[0].loanedAt").value("2026-02-02"))
                .andExpect(jsonPath("$[0].returnedAt").value(org.hamcrest.Matchers.nullValue()))
                .andExpect(jsonPath("$[0].lateFee").value(org.hamcrest.Matchers.nullValue()))
                .andExpect(jsonPath("$[1].loanId").value(onTimeLoanId))
                .andExpect(jsonPath("$[1].title").value("History On Time Book"))
                .andExpect(jsonPath("$[1].loanedAt").value("2026-01-10"))
                .andExpect(jsonPath("$[1].returnedAt").value("2026-01-12"))
                .andExpect(jsonPath("$[1].lateFee").value(0))
                .andExpect(jsonPath("$[2].loanId").value(lateLoanId))
                .andExpect(jsonPath("$[2].title").value("History Late Book"))
                .andExpect(jsonPath("$[2].loanedAt").value("2026-01-01"))
                .andExpect(jsonPath("$[2].returnedAt").value("2026-01-20"))
                .andExpect(jsonPath("$[2].lateFee").value(500));
    }

    @Test
    void member_without_loans_gets_an_empty_array() throws Exception {
        String memberId = registerMember("오지후");

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));
    }

    @Test
    void unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans/history", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    private void returnBook(String loanId, String returnedAt) throws Exception {
        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"" + returnedAt + "\"}"))
                .andExpect(status().isOk());
    }

    private String loanBook(String bookId, String memberId, LocalDate loanedAt) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBody(bookId, memberId, loanedAt))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String registerMember(String name) throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    record LoanBody(String bookId, String memberId, LocalDate loanedAt) {
    }
}

